// Новогодние идеи для свиданий: 200 штук.
// id начинаются с 5001, чтобы не пересекаться с основной базой (1–2233):
// список «Удалённые» хранит идеи по id, общие номера путали бы идеи.
// title — название, text — описание. Метки budget/location/mood
// проставлены автоматически по тексту, как в основной базе.
const newYearIdeas = [
{"id": 5001,"title": "Почта Северного сияния","text": "Превратите комнату в сказочное почтовое отделение, где письма доставляются не по адресам, а прямо в сердца. Подготовьте друг для друга несколько конвертов с загадочными заданиями, признаниями и маленькими сюрпризами, спрятав их в неожиданных уголках дома. Каждое найденное письмо будет приближать вас к главному посланию вечера — признанию, которое вы давно хотели произнести.","budget": "free","location": "home","mood": "romantic"},{"id": 5002,"title": "Тайна исчезнувшей новогодней звезды","text": "Представьте, что главная звезда Нового года таинственно исчезла и только вы вдвоём способны её вернуть. Создайте небольшой детективный квест с записками, зашифрованными подсказками и заданиями, каждое из которых раскрывает новую часть истории. Финалом станет найденная бумажная звезда, внутри которой спрятано желание, предназначенное только для вас двоих.","budget": "free","location": "home","mood": "active"},{"id": 5003,"title": "Волшебная лавка забытых желаний","text": "Устройте маленькую лавку чудес, где вместо денег принимаются комплименты, воспоминания и поцелуи. Разложите красиво упакованные коробочки с необычными подарками: обещанием приключения, правом загадать желание или секретным признанием. По очереди становитесь продавцом и покупателем, превращая каждый обмен в трогательную новогоднюю историю.","budget": "free","location": "home","mood": "romantic"},{"id": 5004,"title": "Зимний театр оживших теней","text": "Погасите основной свет, включите фонарик и превратите обычную стену в сцену сказочного театра. Вырежьте из бумаги силуэты двух путешественников, снежного замка и волшебных существ, а затем вместе придумайте историю о любви, победившей вечную зиму. Самую красивую сцену завершите настоящим поцелуем, чтобы сказка неожиданно вышла за пределы театра.","budget": "free","location": "home","mood": "creative"},{"id": 5005,"title": "Снежный шар с тайным посланием","text": "Создайте собственный снежный мир в прозрачной баночке, используя миниатюрные фигурки, бумажные домики и искусственный снег. Пусть каждый добавит туда один символ того, что делает ваши отношения особенными, не объясняя свой выбор до самого конца. Когда маленькая вселенная будет готова, расскажите друг другу истории этих символов и придумайте название вашему волшебному миру.","budget": "free","location": "home","mood": "creative"},{"id": 5006,"title": "Двенадцать дверей будущего","text": "Смастерите двенадцать маленьких конвертов, каждый из которых будет символизировать один месяц наступающего года. По очереди открывайте их и вытягивайте задания: придумать неожиданное свидание, загадать совместную мечту или дать романтическое обещание. В конце у вас появится настоящий календарь будущих приключений, в котором каждый месяц хранит частичку новогоднего волшебства.","budget": "free","location": "home","mood": "romantic"},{"id": 5007,"title": "Агентство по поиску чудес","text": "Объявите себя тайными инспекторами новогоднего волшебства, которым необходимо обнаружить семь чудес за один вечер. Составьте список загадочных объектов для поиска — например, самого уютного света, самой счастливой фотографии и вещи, хранящей особенно нежное воспоминание. За каждую находку вручайте друг другу нарисованную звезду, а собрав все семь, обменяйте их на исполнение маленьких желаний.","budget": "free","location": "home","mood": "active"},{"id": 5008,"title": "Алхимики зимнего счастья","text": "Представьте, что вы ученики древней школы волшебства, которым поручили создать эликсир счастья. Подберите безопасные съедобные ингредиенты для необычного зимнего напитка, придумав каждому магическое свойство: корица дарит смелость, мёд — нежность, а апельсин — радость. Смешивайте ингредиенты по очереди, произнося смешные заклинания, а затем попробуйте ваш эликсир, загадав одно желание на двоих.","budget": "paid","location": "home","mood": "food"},{"id": 5009,"title": "Созвездие нашей любви","text": "Выключите свет и превратите потолок или стену в ночное небо с помощью бумажных звёзд и маленьких огоньков. На каждой звезде напишите важное для ваших отношений событие, а затем соедините их нитями в совершенно новое созвездие. Придумайте ему название и легенду, будто где-то в далёкой галактике теперь существует звёздная история вашей любви.","budget": "free","location": "home","mood": "romantic"},{"id": 5010,"title": "Варежка исполнения желаний","text": "Спрячьте в большой варежке множество свёрнутых бумажек с романтическими заданиями и неожиданными привилегиями. Вытягивайте записки по очереди, исполняя то, что вам досталось: станцевать под воображаемым снегопадом, рассказать тайну или подарить пять разных объятий. Одну особенную записку оставьте золотой — её обладатель сможет загадать желание, которое второй постарается исполнить до конца вечера.","budget": "free","location": "home","mood": "romantic"},{"id": 5011,"title": "Лабиринт красной нити","text": "Протяните по комнате длинную красную нитку, обвив её вокруг мебели и прикрепив к ней маленькие записки. Один из вас должен пройти по этому необычному маршруту, выполняя задания, спрятанные на каждом повороте. В конце нить приведёт к любимому человеку, который будет ждать с подарком и словами о том, почему из тысяч дорог он выбрал именно вашу общую.","budget": "free","location": "home","mood": "romantic"},{"id": 5012,"title": "Камин из несказанных историй","text": "Создайте декоративный камин из коробки, бумаги и безопасных светодиодных огоньков, превратив его в очаг зимних воспоминаний. Напишите на бумажных язычках пламени моменты, которые хотели бы пережить вместе, и по очереди рассказывайте, какой могла бы получиться каждая история. Когда ваш камин наполнится мечтами, выберите одну из них и назначьте день, когда она начнёт становиться реальностью.","budget": "free","location": "home","mood": "cozy"},{"id": 5013,"title": "Сон, упакованный в коробку","text": "Каждый тайно собирает небольшую коробку, посвящённую идеальному сказочному вечеру для своей второй половинки. Внутри могут оказаться подсказки, ароматные предметы, рисунки, миниатюрные подарки и задания, которые постепенно раскрывают задуманный сюжет. Обменяйтесь коробками и попробуйте воссоздать мечту друг друга, используя всё, что сможете найти дома.","budget": "free","location": "home","mood": "cozy"},{"id": 5014,"title": "Охотники за звуками зимы","text": "Представьте, что вы создаёте музыкальную шкатулку для Снежной королевы, которая никогда не слышала настоящего счастья. По очереди записывайте на телефон необычные звуки: звон бокалов, шуршание упаковки, смех, хруст печенья и шёпот ласковых слов. Соберите их в маленькую звуковую историю и прослушайте с закрытыми глазами, пытаясь угадать, какое воспоминание скрывается за каждым звуком.","budget": "free","location": "home","mood": "active"},{"id": 5015,"title": "Меню волшебных превращений","text": "Подготовьте набор карточек с названиями сказочных блюд, не раскрывая, какие угощения за ними прячутся. Чтобы получить каждое блюдо, нужно выполнить небольшую миссию: расшифровать послание, отгадать факт о партнёре или придумать романтическое заклинание. Даже обычные фрукты и печенье превратятся в настоящие сокровища зимнего королевства, если открывать их с помощью маленьких чудес.","budget": "free","location": "home","mood": "food"},{"id": 5016,"title": "Королевство подушек и пледов","text": "Постройте в комнате уютную крепость из подушек, одеял и гирлянд, придумав ей сказочное название. Создайте собственные паспорта жителей королевства и необычные законы, например обязательные объятия при пересечении границы или поцелуй за каждое доброе признание. Проведите торжественную коронацию друг друга и устройте тайный совет, на котором решите, какие чудеса обязательно должны произойти в новом году.","budget": "free","location": "home","mood": "cozy"},{"id": 5017,"title": "Снегопад из ста добрых слов","text": "Нарежьте бумажные снежинки и напишите на них комплименты, благодарности, смешные воспоминания и нежные признания. Сложите их в большую коробку, а затем устройте настоящий комнатный снегопад, одновременно подбросив снежинки над пледом. Собирайте случайно упавшие послания, читайте их вслух и оставьте самые трогательные на память о вашей маленькой снежной буре.","budget": "free","location": "home","mood": "romantic"},{"id": 5018,"title": "Тайная библиотека двух сердец","text": "Превратите несколько книг или самодельных книжечек в таинственную библиотеку, где каждая обложка скрывает историю о ваших отношениях. Внутрь вложите карточки с названиями несуществующих сказок, например «Как один взгляд остановил время» или «Королевство, где всегда ждали тебя». Выбирайте истории наугад и сочиняйте их вдвоём, постепенно создавая собственную романтическую книгу.","budget": "free","location": "home","mood": "creative"},{"id": 5019,"title": "Зеркало добрых предсказаний","text": "Украсьте зеркало бумажными звёздами, снежинками и карточками с загадочными предсказаниями. По очереди подходите к нему с закрытыми глазами, вытягивайте одну карточку и узнавайте, какое романтическое чудо обещает вам наступающий год. Чтобы предсказание обрело силу, придумайте маленький шаг, который поможет ему исполниться, и скрепите обещание поцелуем.","budget": "free","location": "home","mood": "romantic"},{"id": 5020,"title": "Хранители последней минуты","text": "Представьте, что волшебные часы остановились и Новый год сможет наступить только после выполнения двенадцати маленьких заданий. Подготовьте двенадцать карточек с вопросами, испытаниями и признаниями, а затем запускайте минутный таймер на каждую миссию. Когда все задания будут выполнены, торжественно переведите стрелки нарисованных часов на полночь и устройте собственный волшебный отсчёт.","budget": "free","location": "home","mood": "romantic"},{"id": 5021,"title": "Охота за золотыми окнами","text": "Отправьтесь на вечернюю прогулку, будто вы исследователи города, в котором спрятаны окна из настоящего золота. Найдите пять особенно красиво освещённых окон и придумайте, какая волшебная история могла бы происходить за каждым из них. За последним окном сочините сказку о двух влюблённых, которые однажды нашли самый тёплый свет не в чужом доме, а друг в друге.","budget": "free","location": "outdoor","mood": "active"},{"id": 5022,"title": "Секретная экспедиция Деда Мороза","text": "Подготовьте карту ближайших улиц, отметив на ней несколько точек с загадочными названиями вместо настоящих адресов. В каждой точке один из вас должен выполнить новогоднюю миссию: найти определённый символ, отгадать загадку или получить спрятанное в кармане послание. Когда все испытания будут пройдены, вручите друг другу удостоверения почётных помощников зимнего волшебника.","budget": "free","location": "home","mood": "romantic"},{"id": 5023,"title": "Расследование снежного детектива","text": "Представьте, что кто-то похитил первый снег из сказочного королевства, оставив лишь странные улики. Один заранее готовит небольшие карточки с загадками, а второй ищет ответы среди зимних деталей окружающего мира, получая следующую подсказку за каждое разгаданное сообщение. Финальной уликой окажется признание, что настоящее волшебство всё это время пряталось рядом с ним.","budget": "free","location": "home","mood": "food"},{"id": 5024,"title": "Карта самых тёплых мест","text": "Возьмите небольшую карту района и договоритесь найти пять мест, где даже холодным вечером можно почувствовать душевное тепло. В каждом месте придумывайте особый ритуал: обменяться комплиментами, согреть руки друг друга или рассказать любимое зимнее воспоминание. Отметьте найденные точки сердечками, создав вашу личную карту тепла, к которой можно будет возвращаться следующей зимой.","budget": "free","location": "home","mood": "cozy"},{"id": 5025,"title": "Снежная азбука влюблённых","text": "Придумайте собственный секретный алфавит, в котором каждая нарисованная снежинка, звезда или сердечко обозначает определённую букву. Во время прогулки оставляйте друг другу короткие зашифрованные послания на бумаге, а при подходящей погоде рисуйте их на снегу. Попробуйте расшифровать признания друг друга, а затем объедините ваши символы в один тайный любовный пароль.","budget": "free","location": "outdoor","mood": "creative"},{"id": 5026,"title": "Семь паролей зимнего города","text": "Выберите семь остановок для прогулки и заранее придумайте для каждой секретный пароль, связанный с вашими чувствами. Чтобы узнать следующий пароль, один из вас должен выполнить задание другого: угадать воспоминание, выбрать из трёх признаний самое правдивое или разгадать короткую загадку. Последний пароль станет особенным словом, которое отныне будет означать «я хочу снова пережить этот вечер».","budget": "free","location": "outdoor","mood": "active"},{"id": 5027,"title": "Путешествие за украденной полуночью","text": "Представьте, что таинственный злодей спрятал полночь в одном из уголков вашего города и теперь новогодние часы не могут пробить двенадцать. Создайте маршрут из нескольких безопасных точек и собирайте на каждой бумажные цифры, выполняя романтические задания. Сложив все цифры в правильном порядке, найдите последнюю подсказку, которая приведёт вас к маленькому подарку и символическому наступлению Нового года.","budget": "free","location": "home","mood": "active"},{"id": 5028,"title": "Компас случайных чудес","text": "Возьмите монетку и договоритесь, что орёл означает поворот направо, а решка — налево, выбирая только знакомые и безопасные улицы. На каждом перекрёстке бросайте монетку, а каждые десять минут доставайте карточку со сказочным заданием: придумать название улице, найти красивую деталь или обменяться неожиданными признаниями. Завершите путешествие в удобной точке и дайте вашему случайному маршруту имя, будто это новая дорога на карте волшебного королевства.","budget": "free","location": "home","mood": "romantic"},{"id": 5029,"title": "Музей исчезающих мгновений","text": "Отправьтесь искать маленькие зимние чудеса, которые существуют всего несколько мгновений: отражение гирлянды, красивую тень или снежинку на рукаве. Каждую находку фотографируйте и придумывайте ей необычное музейное название и короткую сказочную легенду. В конце соберите виртуальную выставку под названием «Чудеса, которые мы заметили только потому, что были вместе».","budget": "free","location": "outdoor","mood": "creative"},{"id": 5030,"title": "Экспедиция на Северный полюс","text": "Выберите обычное место для прогулки и объявите его целью секретной полярной экспедиции, куда могут попасть только два исследователя любви. Возьмите с собой самодельные экспедиционные паспорта и карточки испытаний, которые необходимо выполнить по дороге: обнаружить следы зимы, найти северную звезду или сделать фото снежной находки. Добравшись до воображаемого полюса, установите маленький бумажный флаг и объявите эту точку территорией ваших будущих приключений.","budget": "free","location": "outdoor","mood": "active"},{"id": 5031,"title": "Клад под зимним небом","text": "Один из вас заранее прячет маленький подарок в безопасном доступном месте или держит его при себе до нужной точки маршрута. Второй получает карту с загадками, где вместо обычных указаний написаны сказочные описания: «ищи там, где свет сторожит старое дерево». Найденный клад окажется особенно ценным, если внутри будет не дорогая вещь, а приглашение на ещё одно необычное свидание.","budget": "free","location": "home","mood": "active"},{"id": 5032,"title": "Королевский патруль снежинок","text": "Представьте, что вы хранители зимнего королевства, которым поручено найти снежинки пяти необычных видов. Если выпал снег, ищите их настоящие узоры на варежках и тёмной ткани, а если снега нет — заранее подготовьте карточки с нарисованными снежинками и заданиями. За каждую найденную снежинку придумывайте сказочное заклинание, а в конце создайте из всех находок ваш личный герб зимы.","budget": "free","location": "home","mood": "active"},{"id": 5033,"title": "Прогулка без слов","text": "Начните вечер с таинственного правила: на протяжении первых пятнадцати минут нельзя разговаривать, зато можно общаться записками и жестами. Заранее подготовьте маленькие карточки с вопросами, признаниями и заданиями, которые вы будете передавать друг другу по дороге. Когда молчание закончится, расскажите, какое из невысказанных чувств оказалось самым сильным, и позвольте первому поцелую стать вашим главным ответом.","budget": "free","location": "outdoor","mood": "active"},{"id": 5034,"title": "Пять чувств зимнего волшебства","text": "Составьте маршрут с пятью остановками, каждая из которых посвящена одному из чувств. На первой найдите самый красивый свет, на второй прислушайтесь к звукам зимы, на третьей угадайте аромат из принесённого мешочка, на четвёртой попробуйте зимнее угощение, а на пятой согрейте ладони друг друга. Запишите впечатления от каждой остановки и придумайте, каким был бы аромат, звук и цвет вашей любви.","budget": "free","location": "home","mood": "food"},{"id": 5035,"title": "Станция горячих признаний","text": "Возьмите с собой термос с ароматным напитком и набор маленьких карточек, на которых написаны незаконченные романтические фразы. На каждой выбранной остановке открывайте термос, вытягивайте вопрос и завершайте фразу, например «Если бы наша любовь была зимней сказкой, она называлась бы…». Последнюю чашку разделите под красивым светом фонарей, загадав приключение, которое обязательно захотите пережить вместе.","budget": "free","location": "home","mood": "romantic"},{"id": 5036,"title": "Письмо, которое нашло дорогу домой","text": "Перед прогулкой каждый пишет другому небольшое письмо, но оставляет его незапечатанным. По дороге выполняйте маленькие задания и после каждого добавляйте в письмо новую строчку о том, что почувствовали, заметили или вспомнили. Вернувшись домой, обменяйтесь уже завершёнными посланиями, которые стали настоящей историей вашего зимнего путешествия.","budget": "free","location": "outdoor","mood": "romantic"},{"id": 5037,"title": "Дворец танцующих теней","text": "Найдите спокойное место с красивым светом фонарей и превратите ваши тени в персонажей зимней сказки. Придумайте для них имена, устройте безмолвный танец и попробуйте создать из ваших силуэтов самые необычные фигуры. Сделайте фотографию момента, когда тени соединятся, будто два сказочных героя наконец встретились после долгой разлуки.","budget": "free","location": "home","mood": "active"},{"id": 5038,"title": "География волшебных объятий","text": "Нарисуйте простую карту прогулки и обозначьте на ней несколько вымышленных стран: Королевство Нежности, Остров Смеха, Долину Благодарности и Зимний лес Желаний. Добравшись до каждой территории, выполняйте её особый ритуал — от объятий с закрытыми глазами до признания, о котором раньше стеснялись сказать. Когда пройдёте все страны, придумайте название нового государства, которое существует только там, где вы рядом.","budget": "free","location": "outdoor","mood": "romantic"},{"id": 5039,"title": "Атлас несуществующих домов","text": "Во время вечерней прогулки выбирайте необычные здания и представляйте, что каждое из них скрывает вход в сказочный мир. Один придумывает, кто живёт внутри, а второй — какое волшебство там происходит и какое испытание нужно пройти, чтобы войти. Соберите несколько таких историй в заметках телефона и завершите путешествие рассказом о доме, где однажды будут храниться ваши самые счастливые воспоминания.","budget": "free","location": "outdoor","mood": "active"},{"id": 5040,"title": "Последний фонарь перед чудом","text": "Заранее выберите красивое место с фонарём, которое станет тайной финальной точкой вашего маршрута. По дороге соберите пять символических ключей — маленьких бумажных звёзд за исполненные задания, раскрытые секреты и подаренные признания. Под последним фонарём соедините ключи в одну бумажную гирлянду, откройте приготовленный конверт и узнайте, какое романтическое чудо ждёт вас в конце этого путешествия.","budget": "free","location": "home","mood": "romantic"},{"id": 5041,"title": "Ателье снежных заклинаний","text": "Откройте на один вечер волшебное ателье, где обычные бумажные снежинки превращаются в талисманы счастья. Каждый вырезает необычный узор и прячет среди его линий маленькое послание, которое второй должен отыскать и расшифровать. Готовые снежинки повесьте на окно, чтобы всю зиму они напоминали о тайных заклинаниях, созданных вашими руками.","budget": "free","location": "home","mood": "creative"},{"id": 5042,"title": "Миниатюрный город двух влюблённых","text": "Постройте из бумаги и картона крошечный заснеженный город, где каждая улица названа в честь вашего общего воспоминания. По очереди добавляйте новые здания и придумывайте, какие романтические чудеса случаются внутри: в одном доме хранятся поцелуи, в другом исполняются желания. Когда город будет готов, поселите в нём две маленькие фигурки и устройте для них первое новогоднее приключение.","budget": "free","location": "home","mood": "romantic"},{"id": 5043,"title": "Фонарики потерянных желаний","text": "Создайте несколько бумажных фонариков, украсив их звёздами, снежинками и тайными символами, а внутрь поместите безопасные светодиодные свечи. На каждом фонарике напишите мечту, которую однажды перестали считать возможной, и предложите друг другу придумать, как сделать к ней первый шаг. Расставьте ваши огоньки по комнате, превратив её в тихий сад желаний, которые снова начали светиться.","budget": "free","location": "home","mood": "romantic"},{"id": 5044,"title": "Больница разбитых звёзд","text": "Найдите старые или повреждённые ёлочные украшения, которым можно подарить вторую жизнь, не используя острых осколков. Превратитесь в сказочных лекарей и восстановите игрушки с помощью лент, бумаги, красок и маленьких записок с добрыми словами. Каждое спасённое украшение получит новую легенду и станет символом того, что даже несовершенные вещи могут хранить удивительную красоту.","budget": "free","location": "home","mood": "active"},{"id": 5045,"title": "Парфюмерная лавка зимних воспоминаний","text": "Подготовьте маленькие мешочки с корицей, сушёной апельсиновой кожурой, ванилью, хвоей и другими приятными зимними ароматами. С закрытыми глазами угадывайте запахи, рассказывайте, какие чувства они вызывают, и выбирайте ингредиенты для собственного ароматного саше. Дайте получившимся композициям романтические названия, чтобы однажды знакомый аромат мог вернуть вас в этот вечер.","budget": "paid","location": "home","mood": "food"},{"id": 5046,"title": "Нити, соединяющие мечты","text": "Возьмите несколько цветных лент и договоритесь, что каждая обозначает отдельную часть вашей общей жизни: путешествия, уют, открытия, нежность и приключения. По очереди вплетайте ленты в небольшой узор, рассказывая, чего хотите добавить в каждую из этих историй в новом году. Готовое переплетение превратите в украшение, которое будет напоминать, как красиво могут соединяться две разные мечты.","budget": "free","location": "home","mood": "romantic"},{"id": 5047,"title": "Рождение маленького зимнего духа","text": "Создайте из носочка, ткани или бумаги собственного сказочного персонажа, который станет хранителем ваших отношений. Каждый по очереди добавляет ему деталь и придумывает новую способность: охранять счастливые моменты, возвращать улыбки или подсказывать путь к примирению. Когда дух будет готов, устройте церемонию посвящения и доверьте ему ваше первое совместное желание на новый год.","budget": "free","location": "home","mood": "creative"},{"id": 5048,"title": "Вышивка невидимых обещаний","text": "Нарисуйте на плотном картоне большое сердце или зимнюю звезду и сделайте по контуру небольшие отверстия. Продевайте через них цветные нити, создавая общий узор, и сопровождайте каждый новый стежок добрым обещанием или признанием. В итоге получится необычный талисман, в котором ваши слова будут буквально переплетены друг с другом.","budget": "free","location": "home","mood": "romantic"},{"id": 5049,"title": "Дверь в другую зиму","text": "Вырежьте из картона маленькую декоративную дверь и договоритесь, что за ней находится волшебный мир, придуманный вами двоими. Каждый тайно создаёт на отдельном листе часть этого мира — его обитателей, зимние праздники, загадочные места и законы любви. Откройте дверь, соедините ваши фантазии и придумайте первое приключение, которое могло бы произойти по ту сторону.","budget": "free","location": "home","mood": "creative"},{"id": 5050,"title": "Королевская печать любви","text": "Сделайте собственную печать из простых материалов, например вырежьте знак на кусочке картофеля и используйте краску для бумаги. Придумайте для вашего символа тайное значение, которое сможете понять только вы двое, и украсьте им несколько открыток с секретными заданиями. В будущем эта печать сможет появляться на неожиданных посланиях, обещая маленький сюрприз от любимого человека.","budget": "free","location": "home","mood": "creative"},{"id": 5051,"title": "Созвездия на зимних варежках","text": "Нарисуйте на бумаге силуэты варежек и предложите друг другу украсить их точками-звёздами, символизирующими ваши самые дорогие воспоминания. Обменяйтесь рисунками и попробуйте угадать, какая история скрывается за каждым маленьким созвездием. Затем соедините бумажные варежки лентой и повесьте на видное место как знак того, что даже в самую холодную зиму ваши руки всегда найдут друг друга.","budget": "free","location": "home","mood": "creative"},{"id": 5052,"title": "Колокольчики счастливых случайностей","text": "Соберите небольшой декоративный музыкальный мобиль из ленточек, лёгких колокольчиков и бумажных звёздочек. На каждой звезде напишите счастливую случайность, благодаря которой вы стали ближе, а затем прикрепите её к общей композиции. Когда мобиль будет готов, осторожно позвените колокольчиками и придумайте, какое новое прекрасное совпадение вы хотели бы однажды встретить.","budget": "free","location": "home","mood": "creative"},{"id": 5053,"title": "Портреты из снежинок","text": "Попробуйте создать портреты друг друга, используя только вырезанные из бумаги снежинки, звёзды и маленькие сердечки. Вместо реалистичного сходства передайте характер любимого человека через формы: дерзкие лучи, нежные узоры или причудливые завитки. После обмена портретами расскажите, почему выбрали именно такие детали, и устройте крошечную выставку зимних душ.","budget": "free","location": "home","mood": "creative"},{"id": 5054,"title": "Лента двенадцати сокровищ","text": "Подготовьте длинную красивую ленту и двенадцать маленьких бумажных подвесок, каждая из которых будет обозначать особенное желание или предстоящее событие. По очереди придумывайте, что должно произойти в каждом месяце, превращая мечты в забавные символы. Повесьте вашу ленту там, где она будет напоминать, что новый год уже наполнен маленькими сокровищами, которые только предстоит открыть.","budget": "free","location": "home","mood": "romantic"},{"id": 5055,"title": "Ёлка невозможных выборов","text": "Создайте из бумаги миниатюрную ёлку и украсьте её карточками с необычными сказочными дилеммами. Представьте, что вам нужно выбрать между путешествием на луну и ночью в ледяном дворце, возможностью остановить время и умением читать мысли любимого человека. Обсуждайте выборы и придумывайте, как хотя бы маленькую часть каждой фантазии можно воплотить в реальной жизни.","budget": "free","location": "home","mood": "creative"},{"id": 5056,"title": "Снежная мозаика двух миров","text": "Каждый получает половину большого бумажного круга и создаёт на ней собственную зимнюю вселенную из кусочков цветной бумаги. Договоритесь не показывать рисунки до завершения, чтобы потом попробовать соединить две разные картины в один гармоничный мир. Место соединения украсьте золотой звездой и придумайте легенду о том, как две волшебные зимы однажды встретились.","budget": "free","location": "home","mood": "creative"},{"id": 5057,"title": "Деревня светлячков","text": "Сделайте несколько маленьких бумажных домиков и поставьте внутрь безопасные светодиодные огоньки. В каждом домике спрячьте записку с необычным романтическим заданием, которое можно обнаружить, только открыв его крышу. Когда вся деревня засияет, по очереди выбирайте светящиеся дома и выполняйте миссии их крошечных жителей.","budget": "free","location": "home","mood": "cozy"},{"id": 5058,"title": "Подарок с зашифрованной обёрткой","text": "Подготовьте друг другу маленькие сюрпризы, но вместо обычной подарочной бумаги используйте листы с нарисованными символами и секретными посланиями. Прежде чем открыть подарок, получатель должен разгадать шифр, который подскажет, почему именно этот предмет был выбран. Самой ценной частью станет не содержимое коробочки, а романтическая история, спрятанная на её поверхности.","budget": "free","location": "home","mood": "creative"},{"id": 5059,"title": "Амулеты первого снегопада","text": "Приготовьте простое солёное тесто и вылепите два небольших талисмана, каждый для другого человека. Пока украшения сохнут, придумайте им волшебные свойства и объясните, какие хорошие моменты они должны притягивать в следующем году. Раскрасьте готовые фигурки и обменяйтесь ими на маленькой церемонии, пообещав беречь не только амулеты, но и связанные с ними мечты.","budget": "free","location": "home","mood": "food"},{"id": 5060,"title": "Шкатулка с двойным дном","text": "Создайте из небольшой коробки волшебную шкатулку с секретным отделением, которое можно сделать из дополнительной картонной перегородки. В обычной части положите забавные мелочи и отвлекающие загадки, а в потайной спрячьте особенно нежное письмо или приглашение на секретное приключение. Предложите любимому человеку исследовать шкатулку, не предупреждая, что главное сокровище находится гораздо глубже, чем кажется.","budget": "free","location": "home","mood": "romantic"},{"id": 5061,"title": "Машина времени наоборот","text": "Превратите комнату в секретную лабораторию, где можно путешествовать по воспоминаниям, двигаясь не вперёд, а назад. Подготовьте карточки с важными событиями ваших отношений и вытягивайте их в обратном порядке, стараясь воссоздать атмосферу каждого момента с помощью жестов, музыки или маленьких предметов. Добравшись до самого первого воспоминания, расскажите, что сказали бы себе тогда, если бы уже знали, какая прекрасная история вас ожидает.","budget": "free","location": "home","mood": "romantic"},{"id": 5062,"title": "Интервью из 2046 года","text": "Представьте, что вы встретились спустя двадцать лет, а один из вас стал журналистом, которому поручили взять интервью у счастливой пары. Придумайте свою будущую жизнь и отвечайте на необычные вопросы о приключениях, семейных традициях, любимых местах и секретах долгой любви. В конце поменяйтесь ролями и сравните ваши фантазии, чтобы обнаружить мечты, которые удивительным образом совпадают.","budget": "free","location": "home","mood": "romantic"},{"id": 5063,"title": "Двенадцать параллельных Новых годов","text": "Напишите на двенадцати карточках названия альтернативных миров: ледяная планета, сказочное королевство, космический корабль, город вечной зимы и другие. Вытягивайте карточки по очереди и разыгрывайте короткие сцены о том, как вы праздновали бы Новый год, оказавшись в этих вселенных. Выберите мир, в который захотели бы вернуться, и придумайте, как устроить посвящённое ему настоящее свидание.","budget": "free","location": "home","mood": "creative"},{"id": 5064,"title": "Новогодний экспресс воспоминаний","text": "Расставьте дома несколько импровизированных станций, каждая из которых будет обозначать определённый период вашей совместной истории. Создайте билеты и объявления для пассажиров, а на каждой остановке выполняйте задания, связанные с прошлым: повторить смешной разговор, вспомнить первый подарок или показать знакомый жест. Последней станцией станет «Будущее», где вас будет ждать пустой билет для совершенно нового приключения.","budget": "free","location": "home","mood": "creative"},{"id": 5065,"title": "Первое знакомство в другой вселенной","text": "Представьте, что вы никогда раньше не встречались, но судьба решила познакомить вас на старинном новогоднем балу. Придумайте себе необычные имена, биографии и маленькие секреты, а затем разыграйте первую встречу, будто вы совершенно незнакомые люди. Попробуйте влюбить друг друга заново, используя только разговоры, загадки и очарование этой придуманной зимней ночи.","budget": "free","location": "home","mood": "creative"},{"id": 5066,"title": "Открытки из ещё не случившегося отпуска","text": "Создайте открытки, будто вы уже вернулись из волшебного зимнего путешествия, которое пока существует только в мечтах. Нарисуйте несуществующие пейзажи и опишите друг другу самые яркие моменты будущей поездки, включая смешные происшествия и романтические сюрпризы. После обмена открытками выберите одну деталь, которую сможете воплотить в ближайшие месяцы.","budget": "free","location": "home","mood": "creative"},{"id": 5067,"title": "Музей будущих воспоминаний","text": "Устройте дома выставку предметов, которые якобы остались после ваших прекрасных приключений в следующем году. Обычная пуговица может стать сувениром с таинственного бала, камешек — находкой из путешествия, а билетик — пропуском в день невероятного счастья. По очереди проводите экскурсии по этому музею и рассказывайте истории событий, которые ещё только предстоит создать вместе.","budget": "free","location": "home","mood": "cozy"},{"id": 5068,"title": "Письмо от вашей будущей пары","text": "Каждый пишет послание от имени вас двоих через десять лет, будто ваша будущая версия решила передать совет сегодняшним влюблённым. Опишите маленькие привычки, которые помогли сохранить нежность, удивительные приключения и моменты, когда вы особенно гордились друг другом. Прочитайте письма вслух и выберите одну традицию, которую сможете начать уже сегодня.","budget": "free","location": "home","mood": "romantic"},{"id": 5069,"title": "Новогоднее послание себе из прошлого","text": "Подготовьте две красивые открытки, адресованные себе в тот период жизни, когда вы ещё не знали друг друга. Расскажите своему прошлому «я» о самом неожиданном счастье, которое подарило вам это знакомство, оставив имя любимого человека загадкой до последних строк. Обменяйтесь письмами и прочитайте их так, будто получили волшебную почту из другого времени.","budget": "free","location": "home","mood": "creative"},{"id": 5070,"title": "Суд над уходящим годом","text": "Устройте сказочное судебное заседание, на котором уходящий год предстанет перед вами за все свои странности, испытания и счастливые случайности. Один будет адвокатом, другой — судьёй, а свидетелями станут ваши фотографии, воспоминания и забавные истории. Вынесите году необычный приговор: сохранить самые светлые мгновения навсегда, а все грустные моменты превратить в мудрость и новые надежды.","budget": "free","location": "home","mood": "creative"},{"id": 5071,"title": "Один час вне времени","text": "Объявите, что в течение следующего часа обычные часы больше не имеют власти над вашей жизнью. Подготовьте несколько конвертов с заданиями разной длительности и открывайте их наугад, не глядя на время, позволяя вечеру развиваться неожиданным образом. Когда все приключения завершатся, попробуйте угадать, сколько времени прошло, и расскажите, в какой момент вам особенно хотелось его остановить.","budget": "free","location": "home","mood": "romantic"},{"id": 5072,"title": "Изобретатели традиций будущего","text": "Представьте, что вам поручили придумать новогодние традиции для людей, которые будут жить через сто лет. Создавайте необычные ритуалы, например обмениваться придуманными созвездиями, прятать пожелания в бумажных кометах или встречать полночь тайным рукопожатием. Испытайте самые интересные традиции на себе и выберите одну, которая станет ежегодным секретом вашей пары.","budget": "free","location": "home","mood": "romantic"},{"id": 5073,"title": "Снежинка, останавливающая время","text": "Сделайте бумажную снежинку и договоритесь, что тот, кто держит её в руках, способен на одну минуту остановить время. Во время такой остановки можно загадать вопрос, попросить объятие, поделиться воспоминанием или просто молча смотреть друг другу в глаза. Передавайте снежинку по очереди, пока не поймёте, какие мгновения вам хотелось бы сохранить навсегда.","budget": "free","location": "home","mood": "creative"},{"id": 5074,"title": "Часовщики счастливых секунд","text": "Нарисуйте большой циферблат с двенадцатью делениями и вместо цифр разместите романтические задания. По очереди вращайте самодельную стрелку и выполняйте то, на что она укажет: придумать мини-свидание за пять минут, рассказать секрет или подарить особенный танец. Когда стрелка совершит полный круг, нарисуйте в центре часов символ вашего самого счастливого момента вечера.","budget": "free","location": "home","mood": "creative"},{"id": 5075,"title": "Посланник прошлого Нового года","text": "Один из вас становится таинственным гостем из прошлого декабря и приносит пакет с воспоминаниями, вопросами и предсказаниями. Второй должен угадать, какие желания того времени уже сбылись, что изменилось и какие сюрпризы невозможно было предвидеть. После игры поменяйтесь ролями и напишите новую порцию предсказаний для вашей будущей встречи.","budget": "free","location": "home","mood": "active"},{"id": 5076,"title": "Почта до следующей весны","text": "Напишите друг другу письма, которые разрешается открыть только с наступлением весны. Вместо обычных признаний вложите внутрь маленькие миссии: заметить первые цветы, устроить свидание под весенним дождём или найти место, где вам захочется загадать новое желание. Запечатайте конверты и украсьте их зимними рисунками, будто сама зима передаёт весне секретное послание о вашей любви.","budget": "free","location": "home","mood": "romantic"},{"id": 5077,"title": "Капсула одной прекрасной зимы","text": "Подготовьте коробку, которую наполните символами нынешней зимы: записками, фотографиями, маленькими предметами и предсказаниями. Каждый добавляет несколько секретных вещей, не раскрывая их смысл, а затем записывает вопросы, на которые вам предстоит ответить при следующем открытии. Спрячьте капсулу до следующего Нового года и придумайте специальный пароль, который позволит вновь заглянуть в вашу маленькую машину времени.","budget": "free","location": "home","mood": "creative"},{"id": 5078,"title": "Газета из счастливого будущего","text": "Сделайте собственный выпуск новогодней газеты, где все заголовки рассказывают о ваших ещё не случившихся прекрасных событиях. Придумывайте сенсации вроде «Двое влюблённых случайно нашли самое красивое место на земле» или «Секрет идеального утра наконец раскрыт». По очереди становитесь репортёрами и берите друг у друга интервью о том, как удалось совершить все эти удивительные открытия.","budget": "free","location": "home","mood": "creative"},{"id": 5079,"title": "Аукцион драгоценных минут","text": "Раздайте друг другу одинаковое количество бумажных монеток и устройте сказочный аукцион будущих совместных мгновений. Выставляйте на торги необычные лоты: десять минут танцев под снегопадом, час объятий без телефонов или тайное приключение в ближайшие выходные. Победитель получает красиво оформленный сертификат, а проигравший — право придумать ещё более романтичный лот.","budget": "free","location": "home","mood": "active"},{"id": 5080,"title": "Календарь скрытого свидания","text": "Сделайте необычный календарь, в котором вместо чисел будут нарисованы символы зимы, звёзды, ключики и снежинки. Один из вас тайно выбирает дату будущего свидания и зашифровывает её с помощью нескольких загадок, спрятанных на страницах. Второй должен разгадать день и получить первую подсказку о приключении, которое в этот день начнётся.","budget": "free","location": "home","mood": "creative"},{"id": 5081,"title": "Печенье потерянных созвездий","text": "Испеките или возьмите готовое печенье и украсьте его глазурью так, чтобы на каждом появилась схема необычного созвездия. Придумайте легенду для каждого рисунка и спрячьте за ним романтическое задание, которое второй узнает только после того, как угадает название созвездия. Соберите все звёзды на одной тарелке, словно перед вами лежит съедобная карта неба, где исполняются желания влюблённых.","budget": "free","location": "home","mood": "food"},{"id": 5082,"title": "Лаборатория загадочных вкусов","text": "Соберите несколько закрытых коробочек с простыми съедобными ингредиентами, которые могут интересно сочетаться между собой. По очереди выбирайте коробочки наугад и придумывайте из выпавших продуктов маленькие десерты, давая им названия магических зелий. Устройте торжественную дегустацию и наградите друг друга титулами главных алхимиков новогоднего счастья.","budget": "paid","location": "home","mood": "food"},{"id": 5083,"title": "Пряничный домик с тайной комнатой","text": "Создайте небольшой домик из готового печенья, глазури и сладостей, но заранее договоритесь спрятать внутри крошечное послание в закрытом бумажном конверте. По очереди придумывайте историю каждой комнаты и украшайте стены символами счастливых воспоминаний. Когда строительство закончится, откройте тайную комнату и узнайте, какое романтическое приключение приготовил для вас её невидимый обитатель.","budget": "free","location": "home","mood": "food"},{"id": 5084,"title": "Кондитеры под прикрытием","text": "Представьте, что вы тайные агенты сказочной кондитерской, которым поручили создать десерт по секретному рецепту. Разделите инструкции на две части так, чтобы ни у кого не оказалось полного описания, и попробуйте собрать угощение, обмениваясь только подсказками и загадками. Когда миссия завершится, придумайте кодовое название вашему десерту и сфотографируйте его для секретного архива.","budget": "free","location": "home","mood": "food"},{"id": 5085,"title": "Дегустация украденных воспоминаний","text": "Подготовьте несколько знакомых сладостей и продуктов, связанных с вашим детством, праздниками или совместными встречами. По очереди пробуйте их с закрытыми глазами, угадывайте вкус и рассказывайте, какое воспоминание он неожиданно вернул. В конце придумайте собственное угощение, вкус которого отныне будет ассоциироваться только с вами двумя.","budget": "paid","location": "home","mood": "food"},{"id": 5086,"title": "Рецепт, который нужно расколдовать","text": "Запишите рецепт простого новогоднего десерта, заменив названия ингредиентов сказочными загадками. Например, сахар может называться «песком из королевства облаков», а корица — «пылью из драконьей сокровищницы». Разгадывайте состав вместе и готовьте угощение, словно возвращаете древней книге заклинаний её потерянную магию.","budget": "paid","location": "home","mood": "food"},{"id": 5087,"title": "Турнир волшебных десертов","text": "Разделите небольшой набор сладостей, фруктов и украшений на две равные части, чтобы каждый мог создать собственный миниатюрный десерт. Перед началом вытяните тему, например «Первый снег любви», «Поцелуй Северного сияния» или «Тайна зимнего леса», и постарайтесь воплотить её во вкусе и оформлении. Вместо обычной оценки обменяйтесь романтическими историями о своих творениях и подарите друг другу сладкие награды.","budget": "free","location": "home","mood": "food"},{"id": 5088,"title": "Паспорт путешественников по миру специй","text": "Подготовьте карточки с названиями пряностей и придумайте, что каждая из них является отдельным сказочным государством. Создайте паспорта путешественников и отправляйтесь по ароматным странам, исследуя запахи, придумывая местные легенды и получая символические штампы. В финале смешайте понравившиеся пряности в ароматную смесь для зимнего напитка, которая станет вашим сувениром из волшебного путешествия.","budget": "free","location": "home","mood": "creative"},{"id": 5089,"title": "Шоколадная палитра настроений","text": "Создайте небольшой бар горячего шоколада с разными добавками: корицей, ванилью, маршмеллоу, какао и апельсиновой цедрой. Каждый тайно придумывает напиток, который должен передать настроение любимого человека, и выбирает для него особое название. Обменяйтесь чашками и попробуйте разгадать, какие чувства были спрятаны в каждом ароматном сочетании.","budget": "free","location": "home","mood": "food"},{"id": 5090,"title": "Мандариновая лотерея судьбы","text": "Напишите на маленьких бумажных карточках новогодние предсказания и спрячьте их под разложенными на столе мандаринами. По очереди выбирайте фрукты, открывайте послания и выполняйте выпавшие задания, например станцевать вальс, рассказать тайную мечту или придумать зимнее путешествие. После игры используйте мандариновые дольки, чтобы выложить на тарелке символ вашего общего желания.","budget": "free","location": "home","mood": "food"},{"id": 5091,"title": "Торт из двенадцати мечтаний","text": "Приготовьте небольшой десерт из готовых коржей или печенья и украсьте его двенадцатью разными съедобными элементами. Каждый элемент должен обозначать определённое совместное желание, которое вы будете добавлять в украшение по очереди, рассказывая его историю. Когда торт будет готов, выберите первую мечту, которую постараетесь воплотить, прежде чем испечёте следующий такой десерт.","budget": "free","location": "home","mood": "food"},{"id": 5092,"title": "Съедобный снегопад","text": "Превратите стол в маленькую зимнюю страну, используя кокосовую стружку, сахарную пудру и другие подходящие съедобные украшения. Создайте среди сладкого снега миниатюрный пейзаж с дорожками, домиками из печенья и двумя влюблёнными персонажами. По очереди перемещайте героев по вашему миру, придумывая задания и неожиданные встречи, пока они не найдут главное сокровище зимы.","budget": "free","location": "home","mood": "food"},{"id": 5093,"title": "Чайная церемония четырёх стихий","text": "Подготовьте четыре небольшие чашки с разными зимними напитками и придумайте каждой сказочную стихию: снег, звёзды, огонь и северный ветер. За каждой чашкой должен скрываться особый вопрос — о самом тёплом воспоминании, самой смелой мечте, самой неожиданной радости или тайном желании. Пробуйте напитки по очереди и создавайте собственную церемонию, в которой каждый вкус открывает новую сторону вашей любви.","budget": "free","location": "home","mood": "food"},{"id": 5094,"title": "Послание на дне чашки","text": "Сделайте специальные подставки под чашки, на обратной стороне которых будут спрятаны загадки и романтические задания. Выпейте вместе любимый зимний напиток, а затем поднимайте чашки и открывайте послания, будто получили предсказание от доброй волшебницы. Соберите найденные подсказки в правильном порядке, чтобы узнать секретное предложение о вашем следующем свидании.","budget": "free","location": "home","mood": "food"},{"id": 5095,"title": "Портрет любви на печенье","text": "Подготовьте печенье, разноцветную глазурь и маленькие съедобные украшения, чтобы создать необычные портреты друг друга. Не старайтесь передать внешность буквально, а изображайте любимые качества через смешные символы, цветы, звёзды и сказочных животных. После завершения устройте выставку, где каждый объяснит, почему его сладкий портрет получился именно таким.","budget": "free","location": "home","mood": "food"},{"id": 5096,"title": "Волшебный компас вкусов","text": "Нарисуйте большой компас, на котором вместо сторон света будут написаны «Нежность», «Приключение», «Уют» и «Волшебство». Вращайте стрелку и создавайте небольшие угощения из заранее подготовленных продуктов, стараясь передать выпавшее настроение. После каждого блюда рассказывайте, какое реальное свидание соответствовало бы этому вкусу и почему.","budget": "paid","location": "home","mood": "food"},{"id": 5097,"title": "Двенадцать сладких ударов часов","text": "Подготовьте двенадцать маленьких угощений, под каждым из которых спрячьте карточку с новогодним заданием. Устройте собственную символическую полночь, но вместо боя курантов по очереди открывайте сладости и выполняйте выпавшие миссии. Когда последняя карточка будет раскрыта, загадайте общее желание и обменяйтесь самым сладким признанием вечера.","budget": "free","location": "home","mood": "romantic"},{"id": 5098,"title": "Пирог с секретным смыслом","text": "Испеките или украсьте простой пирог, разделив его поверхность на несколько секторов с разными рисунками. Для каждого сектора придумайте отдельное романтическое послание, которое станет известно только после выбора кусочка. Перед тем как попробовать десерт, расскажите историю спрятанного символа и подарите любимому человеку связанную с ним маленькую мечту.","budget": "free","location": "home","mood": "food"},{"id": 5099,"title": "Завтрак из зачарованной зимы","text": "Представьте, что вы проснулись в сказочном замке, где обычный завтрак появляется только после выполнения волшебных испытаний. Подготовьте несколько карточек с заданиями, открывающими доступ к ингредиентам, украшениям и напиткам, чтобы вместе собрать особенный праздничный стол. Придумайте для получившегося завтрака легенду и заверните одну карточку с пожеланием, которую можно будет открыть следующим новогодним утром.","budget": "paid","location": "home","mood": "food"},{"id": 5100,"title": "Невидимый шеф-повар","text": "Один из вас становится загадочным шеф-поваром, который не может прикасаться к продуктам, но способен давать волшебные указания. Второй с закрытым рецептом собирает красивую тарелку из заранее нарезанных фруктов, сладостей и других готовых ингредиентов, следуя исключительно описаниям партнёра. Затем поменяйтесь ролями и выясните, насколько точно вы способны превращать фантазии друг друга в маленькие вкусные чудеса.","budget": "paid","location": "home","mood": "food"},{"id": 5101,"title": "Письмо из Зазеркалья","text": "Напишите друг другу послания зеркальным почерком, чтобы прочитать их можно было только с помощью отражения. Внутри спрячьте загадки, ведущие к новым запискам, подаркам и маленьким романтическим испытаниям. Последнее письмо должно раскрыть тайну сказочного мира за зеркалом, где вы всегда находите дорогу друг к другу.","budget": "free","location": "home","mood": "romantic"},{"id": 5102,"title": "Тайна говорящих теней","text": "Вырежьте из плотной бумаги несколько фигур и букв, которые при освещении фонариком будут отбрасывать тени на стену. Разместите элементы так, чтобы только при правильном сочетании света и расстояния из теней складывалось тайное слово. Разгадав его, любимый человек получит ключ к следующей загадке и постепенно откроет ваше главное новогоднее послание.","budget": "free","location": "home","mood": "creative"},{"id": 5103,"title": "Невидимое письмо зимней феи","text": "Напишите секретную фразу белым восковым мелком на белой бумаге, чтобы она казалась совершенно пустой. Вручите лист вместе с загадкой, намекающей, что слова проявятся, если осторожно раскрасить поверхность акварелью. Когда послание проступит словно по волшебству, предложите выполнить спрятанное в нём романтическое задание.","budget": "free","location": "home","mood": "romantic"},{"id": 5104,"title": "Четыре свидетеля новогодней тайны","text": "Выберите четыре обычных предмета, связанных с вашими отношениями, и придумайте для них роль свидетелей загадочного происшествия. Каждый предмет должен дать одну подсказку о том, где спрятан маленький новогодний подарок, но получить её можно только после правильного ответа на личный вопрос. Объедините свидетельства и раскройте дело, словно вы детективы, расследующие самое романтическое преступление года.","budget": "free","location": "home","mood": "creative"},{"id": 5105,"title": "Имя, спрятанное среди звёзд","text": "Подготовьте несколько карточек с романтическими фразами, первые буквы которых образуют секретное слово. Разложите их среди бумажных звёзд и предложите любимому человеку найти правильный порядок с помощью загадок. Когда шифр будет разгадан, откройте конверт с объяснением, почему это слово стало главным символом вашего новогоднего вечера.","budget": "free","location": "home","mood": "romantic"},{"id": 5106,"title": "Оракул бумажных превращений","text": "Сделайте несколько бумажных предсказателей-оригами, внутри которых будут спрятаны необычные романтические задания. Вместо обычных чисел используйте волшебные символы и предложите друг другу выбирать путь, не зная, какое приключение скрывается за сгибом бумаги. После каждого предсказания добавляйте в общую историю новую деталь, пока не получится сказка о двух путешественниках, которых сама судьба решила соединить.","budget": "free","location": "home","mood": "creative"},{"id": 5107,"title": "Разбитая звезда желаний","text": "Вырежьте большую золотую звезду, напишите на ней особенное признание и разделите на несколько частей, словно это древний артефакт. Спрячьте фрагменты по комнате и придумайте загадку для поиска каждого из них. Когда все кусочки соединятся, слова станут видны целиком, а восстановленная звезда превратится в символ того, как прекрасны истории, которые вы собираете вместе.","budget": "free","location": "home","mood": "romantic"},{"id": 5108,"title": "Голоса из заколдованного леса","text": "Запишите несколько коротких голосовых сообщений, будто их оставили загадочные жители зимнего леса. Каждый персонаж должен давать следующую подсказку только после выполнения задания: от поиска спрятанного символа до ответа на вопрос о ваших отношениях. Последним сообщением станет ваш собственный голос, произносящий слова, которые превратят всю историю в очень личное признание.","budget": "free","location": "home","mood": "active"},{"id": 5109,"title": "Код счастливых воспоминаний","text": "Придумайте четырёхзначный код для маленькой шкатулки с бумажным замком или запечатанного конверта. Каждая цифра должна находиться через загадку о важных для вас датах, событиях и забавных случаях, которые известны только вам двоим. Собрав правильную комбинацию, откройте тайник с особенным сюрпризом и предложением создать ещё одно незабываемое воспоминание.","budget": "free","location": "home","mood": "creative"},{"id": 5110,"title": "Световые послания Северного полюса","text": "Изучите несколько простых букв азбуки Морзе и превратите фонарики в устройства секретной новогодней связи. Передавайте друг другу короткие сообщения световыми вспышками, стараясь расшифровать нежные слова и загадочные приглашения. Завершите игру особым сигналом, который в вашем личном коде будет означать просьбу об объятиях.","budget": "free","location": "home","mood": "active"},{"id": 5111,"title": "Карта ароматных сокровищ","text": "Подготовьте несколько маленьких пакетиков с разными зимними ароматами и нарисуйте карту, где каждая точка обозначена определённым запахом. Чтобы найти следующую подсказку, исследователь должен угадать аромат и отыскать спрятанный неподалёку соответствующий символ. Последний запах приведёт к уютному сюрпризу, который вы сможете разделить вдвоём.","budget": "free","location": "home","mood": "creative"},{"id": 5112,"title": "Переписка двух рождественских эльфов","text": "Придумайте двух сказочных эльфов, которые никак не могут встретиться из-за проказ зимнего волшебника. Напишите от их имени серию писем с загадками, тайными признаниями и заданиями, позволяющими передать друг другу очередную весточку. Когда история завершится, устройте долгожданную встречу эльфов и превратите их сказочный поцелуй в настоящий.","budget": "free","location": "home","mood": "creative"},{"id": 5113,"title": "Язык исчезнувшего королевства","text": "Создайте маленький словарь вымышленного языка, в котором сердечки, снежинки и звёзды обозначают слова и чувства. Составьте на нём несколько загадочных предложений и предложите любимому человеку переводить их, постепенно открывая всё более нежные признания. Последнюю фразу сделайте особенной и договоритесь иногда использовать её вместо привычного «я тебя люблю».","budget": "free","location": "home","mood": "creative"},{"id": 5114,"title": "Карточки загадочного пророчества","text": "Напишите десять отдельных фрагментов сказочного пророчества, которое рассказывает о будущем двух влюблённых. Смешайте карточки и предложите восстановить их порядок с помощью нарисованных символов, скрытых чисел и небольших логических подсказок. Когда пророчество станет понятным, окажется, что оно ведёт к настоящему новогоднему сюрпризу, который уже приготовлен для вас двоих.","budget": "free","location": "home","mood": "food"},{"id": 5115,"title": "Домино романтических секретов","text": "Сделайте самодельное домино, где вместо привычных точек будут изображения ваших общих символов и важных воспоминаний. Каждая выложенная костяшка должна сопровождаться короткой историей, связанной с её рисунком, а совпадающие символы позволят продолжить цепочку. Когда все костяшки соединятся, переверните их и прочитайте заранее написанное на обороте общее послание.","budget": "free","location": "home","mood": "romantic"},{"id": 5116,"title": "Закладки из запретной библиотеки","text": "Спрячьте в нескольких книгах красивые закладки с загадками и фрагментами одного большого любовного письма. Каждая закладка должна содержать подсказку к следующей книге, например описание её обложки, героя или первой буквы названия. Собрав все части письма, вы сможете прочитать историю о том, почему среди миллионов возможных сюжетов самым прекрасным оказался ваш.","budget": "free","location": "home","mood": "cozy"},{"id": 5117,"title": "Подарок под семью заклинаниями","text": "Заверните небольшой сюрприз в несколько слоёв бумаги, прикрепив к каждому новое сказочное испытание. Чтобы снять очередной слой, любимому человеку придётся придумать заклинание, разгадать воспоминание, пройти мини-квест или выполнить трогательное задание. Внутри окажется последний свёрток с признанием, которое объяснит, почему настоящее сокровище невозможно измерить стоимостью подарка.","budget": "free","location": "home","mood": "active"},{"id": 5118,"title": "Мозаика тайного признания","text": "Напишите большое романтическое послание на листе, а затем закройте его маленькими бумажными карточками с заданиями. Каждая выполненная миссия позволит убрать один фрагмент мозаики, постепенно открывая спрятанные слова. Попробуйте угадать всё признание до того, как исчезнет последний кусочек, и придумайте особенную награду за правильный ответ.","budget": "free","location": "home","mood": "romantic"},{"id": 5119,"title": "Семиминутное спасение праздника","text": "Объявите, что волшебная снежная буря заколдовала новогодний праздник и расколдовать его можно всего за семь минут. Подготовьте семь быстрых заданий с поиском предметов, расшифровкой символов и маленькими романтическими испытаниями, установив таймер. Если вам удастся справиться, торжественно включите гирлянду и вручите друг другу медали спасителей новогоднего волшебства.","budget": "free","location": "home","mood": "active"},{"id": 5120,"title": "Операция «Вернуть Рождество»","text": "Создайте целую историю о том, что сказочный злодей похитил мешок с праздничным настроением и оставил странные требования. Чтобы вернуть праздник, вам придётся пройти несколько испытаний: восстановить разрушенную карту, отыскать пароль, собрать новогодний символ и разгадать тайную записку. В финале обнаружится мешочек с маленькими подарками и письмо от самого злодея, который признался, что тоже поверил в вашу любовь.","budget": "free","location": "home","mood": "creative"},{"id": 5121,"title": "Кастинг в академию рождественских эльфов","text": "Представьте, что вы оба поступаете на работу в секретную академию новогоднего волшебства. Придумайте друг другу смешные вступительные испытания: упаковать подарок одной рукой, рассмешить строгого экзаменатора или придумать заклинание счастья за тридцать секунд. После экзамена вручите друг другу дипломы с неожиданными специальностями, например «Мастер сказочных объятий» или «Главный хранитель любимой улыбки».","budget": "free","location": "home","mood": "creative"},{"id": 5122,"title": "Снежная битва признаний","text": "Сомните бумажные листочки с написанными внутри вопросами и заданиями, превратив их в мягкие снежки. Устройте шуточную снежную битву в комнате, договорившись бросать их только в безопасное свободное пространство, а после каждого раунда раскрывайте случайно выбранные записки. Победителем станет не тот, кто точнее бросал снежки, а тот, кому удастся придумать самое трогательное признание.","budget": "free","location": "home","mood": "romantic"},{"id": 5123,"title": "Суд над похитителем поцелуев","text": "Один из вас становится таинственным преступником, который обвиняется в похищении всех новогодних поцелуев. Второй играет сказочного судью, задаёт хитрые вопросы, выслушивает оправдания и требует доказательств искренней любви. В конце вынесите шуточный приговор: вернуть все украденные поцелуи лично их законному владельцу.","budget": "free","location": "home","mood": "romantic"},{"id": 5124,"title": "Ярмарка чудес с волшебной валютой","text": "Создайте домашнюю ярмарку, где вместо обычных денег используются бумажные звёзды, заработанные за романтические задания. Откройте несколько импровизированных палаток с необычными услугами: гаданием на мечтах, продажей счастливых воспоминаний и обменом секретных желаний. Постарайтесь заработать достаточно звёзд, чтобы выкупить главный приз ярмарки — особенное совместное приключение.","budget": "free","location": "outdoor","mood": "romantic"},{"id": 5125,"title": "Сказка с тысячей поворотов","text": "Придумайте начало новогодней истории о двух путешественниках, оказавшихся перед воротами заколдованного замка. После каждой сцены предлагайте друг другу два варианта дальнейшего развития событий и разыгрывайте выбранный путь с помощью предметов, жестов и диалогов. Ваша история будет постоянно меняться, пока герои не найдут волшебный предмет, который позволит исполнить одно настоящее желание.","budget": "free","location": "home","mood": "creative"},{"id": 5126,"title": "Генератор случайных свиданий","text": "Подготовьте три стопки карточек: с местами, сказочными персонажами и романтическими заданиями. Вытягивайте по одной карточке из каждой стопки и придумывайте короткое приключение, объединяющее выпавшие элементы, например «зимний лес», «потерянный дракон» и «тайное признание». Выберите самое необычное сочетание и превратите его в настоящий сценарий для следующего свидания.","budget": "free","location": "home","mood": "romantic"},{"id": 5127,"title": "Мост через долину ледяных сердец","text": "Выложите на полу дорожку из бумажных листов, изображающих волшебный мост над заколдованной пропастью. Чтобы перейти на следующий островок, нужно выполнить задание партнёра: угадать его желание, вспомнить счастливый момент или сказать что-то особенно нежное. Добравшись навстречу друг другу, соедините две половины нарисованного сердца и объявите долину спасённой от вечной зимы.","budget": "free","location": "home","mood": "romantic"},{"id": 5128,"title": "Заколдованные слова","text": "Выберите несколько обычных слов, которые на ближайший час окажутся запрещены волшебным новогодним указом. Каждый раз, случайно произнеся одно из них, нужно вытянуть карточку с романтическим заданием или подарить партнёру небольшой комплимент. Очень скоро обычный разговор превратится в весёлую игру, где даже ошибки становятся поводом для нежности.","budget": "free","location": "home","mood": "romantic"},{"id": 5129,"title": "Колесо пяти новогодних даров","text": "Сделайте самодельную рулетку, разделённую на пять секторов: звук, аромат, прикосновение, вкус и тайное послание. После каждого вращения один должен придумать другому небольшой сюрприз, соответствующий выпавшей категории. Так вы постепенно соберёте целую коллекцию необычных ощущений, которые будут ассоциироваться с этой зимней ночью.","budget": "free","location": "home","mood": "food"},{"id": 5130,"title": "Дуэль добрых волшебников","text": "Представьте, что вы два волшебника, которые соревнуются не в силе заклинаний, а в способности делать друг друга счастливее. Каждый по очереди совершает маленькое доброе чудо: рассказывает трогательную историю, придумывает неожиданное развлечение или исполняет давнюю просьбу. Победителя выбрать невозможно, поэтому в финале объедините силы и создайте одно большое доброе волшебство для вас двоих.","budget": "free","location": "home","mood": "active"},{"id": 5131,"title": "Убежище от Великой метели","text": "Объявите, что за окном бушует воображаемая волшебная метель, а вы оказались последними хранителями огня в зимнем королевстве. Постройте уютное убежище из пледов и подушек, а затем вытягивайте карточки со случайными событиями: исчезли запасы, погас свет, потерялась карта или пришло письмо от снежного духа. Решайте задачи сообща, используя заранее подготовленные предметы, пока не переживёте бурю и не встретите долгожданный сказочный рассвет.","budget": "free","location": "home","mood": "cozy"},{"id": 5132,"title": "Гонки на волшебных оленях","text": "Нарисуйте игровое поле с дорогой к Северному полюсу и подготовьте две маленькие фигурки оленей. Чтобы продвинуться вперёд, нужно выполнять задания, связанные с новогодними загадками, романтическими воспоминаниями и смешными испытаниями. Финальной точкой станет мастерская Деда Мороза, где проигравшего ждёт утешительный подарок, а победителя — право придумать особенное желание.","budget": "free","location": "home","mood": "active"},{"id": 5133,"title": "Три сундука снежной королевы","text": "Подготовьте три красивые коробки, внутри которых будут спрятаны разные варианты завершения новогодней истории. Одна содержит загадку, другая — романтический подарок, а третья — приглашение на неожиданное приключение, причём открыть можно только одну. Чтобы сделать выбор, задавайте друг другу вопросы и разгадывайте подсказки, а после финала разрешите раскрыть тайны двух оставшихся сундуков.","budget": "free","location": "home","mood": "romantic"},{"id": 5134,"title": "Язык безмолвных эльфов","text": "Придумайте историю о двух эльфах, у которых злая волшебница украла способность говорить. Подготовьте карточки с новогодними понятиями, романтическими действиями и сказочными персонажами, которые нужно изображать исключительно жестами и мимикой. За каждое угаданное слово возвращайте себе одну «волшебную букву», пока не соберёте фразу, снимающую заклятие.","budget": "free","location": "home","mood": "creative"},{"id": 5135,"title": "Один день на зимнем троне","text": "Создайте бумажную корону и объявите, что её владелец становится правителем маленького сказочного королевства ровно на пятнадцать минут. Король или королева может издавать только добрые указы: объявить обязательный танец, потребовать рассказать любимое воспоминание или устроить церемонию комплиментов. Затем передайте корону друг другу и завершите игру общим указом, который станет новой традицией вашей пары.","budget": "free","location": "home","mood": "active"},{"id": 5136,"title": "Половинки волшебного сердца","text": "Нарисуйте несколько пар одинаковых сказочных символов на карточках и спрячьте их по комнате. Каждый должен найти собственный набор рисунков, а затем объединить совпадающие пары с находками партнёра. На обороте соединённых карточек будут записаны задания, которые можно выполнить только вместе, словно две половинки одного заклинания.","budget": "free","location": "home","mood": "romantic"},{"id": 5137,"title": "Комната, из которой хочется не уходить","text": "Вместо обычного квеста на побег создайте игру, где цель — не выбраться из комнаты, а найти причины остаться в ней ещё немного. Один заранее прячет несколько загадок, каждая из которых открывает уютный сюрприз: любимую песню, тёплое письмо, неожиданное угощение или маленький подарок. Когда все причины будут найдены, поменяйтесь ролями и придумайте совершенно новый набор волшебных задержек.","budget": "free","location": "home","mood": "active"},{"id": 5138,"title": "Три кубика судьбы","text": "Сделайте три бумажных кубика, на гранях которых напишите разные действия, предметы и романтические настроения. Бросайте их одновременно и выполняйте выпавшее сочетание, например «нарисовать», «звезда» и «нежность» или «разыграть», «подарок» и «загадочность». Чем неожиданнее окажется комбинация, тем интереснее будет искать способ превратить её в маленькое настоящее чудо.","budget": "free","location": "home","mood": "creative"},{"id": 5139,"title": "Новогодние агенты под прикрытием","text": "Придумайте друг другу секретные агентские имена и выдайте закрытые конверты с тайными миссиями. В течение вечера каждый должен незаметно исполнить несколько добрых заданий, например вызвать улыбку определённой фразой, подложить нежную записку или организовать неожиданное объятие. В финале раскройте личности агентов и попробуйте угадать, какие счастливые случайности на самом деле были тщательно спланированы.","budget": "free","location": "home","mood": "creative"},{"id": 5140,"title": "Бинго новогодних чудес","text": "Нарисуйте две карточки бинго, где вместо чисел будут романтические события: услышать неожиданный комплимент, получить три поцелуя, разгадать загадку или придумать совместную мечту. В течение вечера старайтесь незаметно создавать ситуации, которые помогут другому закрывать клетки на своей карточке. Когда кто-то соберёт выигрышную линию, откройте главный приз — совместное исполнение самого красивого задания из оставшихся.","budget": "free","location": "home","mood": "romantic"},{"id": 5141,"title": "Двенадцать кадров одной зимней сказки","text": "Договоритесь создать фотоисторию из двенадцати снимков, каждый из которых будет соответствовать одному удару новогодних часов. Заранее придумайте общий сюжет о двух героях, ищущих настоящее чудо, а затем снимайте сцены с помощью простых декораций, гирлянд и предметов. Объедините фотографии в короткую историю с подписями и сохраните её как ваш собственный новогодний фильм без движущихся кадров.","budget": "free","location": "home","mood": "creative"},{"id": 5142,"title": "Альбом фотографий, которых ещё нет","text": "Создайте альбом будущих воспоминаний, где на каждой странице будет описана фотография, которую вы однажды хотите сделать вместе. Вместо готовых снимков используйте пустые рамки, смешные подписи и зарисовки будущих путешествий или романтических моментов. Выберите одну страницу и попробуйте воплотить её прямо сегодня, словно вы впервые отправились внутрь ещё не существующего воспоминания.","budget": "free","location": "home","mood": "creative"},{"id": 5143,"title": "Волшебная метель на стенах","text": "Вырежьте бумажные узоры и расположите их перед фонариком, чтобы на стенах появились причудливые зимние тени. Попробуйте создать целый теневой пейзаж с летающими снежинками, звёздным небом и очертаниями сказочного замка. Придумайте короткую историю об этом месте и завершите её романтической сценой, когда ваши настоящие тени встретятся среди нарисованной светом метели.","budget": "free","location": "home","mood": "creative"},{"id": 5144,"title": "Портрет при свете северной звезды","text": "Используйте фонарик, цветную прозрачную плёнку и бумагу, чтобы создать необычное освещение для портретов друг друга. Вместо привычных фотографий попробуйте передать разные сказочные образы: хранителя зимы, принцессу северных огней или странника из звёздного королевства. После съёмки обменяйтесь портретами и напишите на обороте по одной фразе о волшебстве, которое видите в любимом человеке.","budget": "free","location": "home","mood": "creative"},{"id": 5145,"title": "Книжка ожившего снегопада","text": "Возьмите небольшой блокнот и нарисуйте на последовательных страницах простую анимацию: падающую снежинку, встречу двух звёзд или постепенно появляющееся сердце. Каждый создаёт половину сюжета, не раскрывая партнёру, какой конец задумал для своей истории. Соедините рисунки, быстро пролистайте страницы и посмотрите, как ваша совместная сказка впервые оживает.","budget": "free","location": "home","mood": "creative"},{"id": 5146,"title": "Новогодний комикс двух авторов","text": "Придумайте смешных сказочных персонажей, внешне немного напоминающих вас, и отправьте их спасать исчезающий Новый год. Рисуйте комикс по очереди: один создаёт сцену и реплику, второй должен придумать неожиданное продолжение, не меняя уже нарисованного. Пусть финал окажется непредсказуемым, но обязательно счастливым, а готовую историю сохраните как первый выпуск вашей маленькой серии.","budget": "free","location": "home","mood": "creative"},{"id": 5147,"title": "Коллаж тайных зимних миров","text": "Подготовьте старые журналы, цветную бумагу, ножницы, клей и несколько конвертов с названиями волшебных мест. Каждый вытягивает место и создаёт для другого сказочную открытку, не называя мир, который ему достался. После обмена попробуйте угадать задуманные вселенные и придумайте, какое приключение вы могли бы пережить в каждой из них.","budget": "free","location": "home","mood": "creative"},{"id": 5148,"title": "Витраж счастливых желаний","text": "Создайте из цветной прозрачной бумаги или плёнки небольшой декоративный витраж с новогодними символами. Каждый выбирает цвета для своих желаний и постепенно добавляет их в общую композицию, объясняя скрытые значения. Когда работа будет готова, поднесите её к окну или безопасному источнику света и полюбуйтесь тем, как две разные палитры превратились в одно сияющее чудо.","budget": "free","location": "home","mood": "romantic"},{"id": 5149,"title": "Фотографии маленьких вселенных","text": "Возьмите телефоны и отправьтесь на поиски красивых деталей, которые обычно остаются незамеченными: узора на стекле, блеска гирлянды или отражения в ложке. Фотографируйте их максимально близко, а затем показывайте друг другу, предлагая угадать, что именно изображено. Из самых необычных снимков создайте альбом «Тайные миры нашей зимы» и придумайте названия каждому обнаруженному чуду.","budget": "free","location": "outdoor","mood": "creative"},{"id": 5150,"title": "Живые ёлочные игрушки","text": "Напишите на карточках названия фантастических ёлочных украшений: танцующая звезда, застенчивый колокольчик, влюблённая снежинка или королевская сосулька. По очереди вытягивайте карточки и изображайте персонажей в смешных позах, пока второй пытается их сфотографировать или угадать. Выберите лучшие фотографии, добавьте праздничные рамки и сделайте цифровую гирлянду из ваших оживших игрушек.","budget": "free","location": "home","mood": "active"},{"id": 5151,"title": "Фильм, который никто не снимал","text": "Придумайте название старинного романтического новогоднего фильма, который якобы потерялся много лет назад. Один из вас становится режиссёром и описывает сцены, а второй играет главного героя, импровизируя реплики, движения и неожиданные повороты сюжета. Поменяйтесь ролями на середине истории и постарайтесь придумать такой финал, который сделал бы вашу вымышленную картину легендой зимнего кино.","budget": "free","location": "home","mood": "creative"},{"id": 5152,"title": "Двойной портрет зимнего чуда","text": "Каждый делает несколько фотографий зимних деталей, которые напоминают ему о любимом человеке. Затем выбирайте по одному снимку и соединяйте их в коллажи, чтобы два совершенно разных изображения образовывали необычную общую картину. Сравните получившиеся работы и расскажите, почему именно эти предметы, цвета и формы стали для вас символами любви.","budget": "free","location": "home","mood": "creative"},{"id": 5153,"title": "Создатели снежных существ","text": "Соберите безопасные подручные материалы — бумагу, ткань, пуговицы, ленты и картон — и попробуйте создать совершенно новое зимнее существо. Каждый добавляет ему по одной детали и придумывает связанную с ней сказочную способность, пока ваш персонаж не обретёт собственный характер. После завершения устройте небольшой спектакль о том, как это чудо впервые встретило двух влюблённых и решило исполнить их желание.","budget": "free","location": "home","mood": "creative"},{"id": 5154,"title": "Афиша самого прекрасного праздника","text": "Представьте, что вы организуете легендарный новогодний фестиваль, на который приглашены всего два человека. Создайте настоящую афишу с названием, сказочной программой, необычными конкурсами и собственным символом праздника. После торжественного открытия фестиваля постарайтесь выполнить хотя бы три пункта придуманной программы, чтобы ваша фантазия превратилась в реальное событие.","budget": "free","location": "home","mood": "creative"},{"id": 5155,"title": "Немое кино о новогодней любви","text": "Снимите на телефон небольшой чёрно-белый фильм, в котором никто не произносит ни слова. Придумайте драматичную историю о потерянном подарке, несостоявшейся встрече или звезде, которая упала прямо в руки влюблённых, передавая чувства только жестами и мимикой. Добавьте короткие текстовые заставки между сценами и устройте домашнюю премьеру вашего собственного романтического кино.","budget": "free","location": "home","mood": "cozy"},{"id": 5156,"title": "Ожившие новогодние предметы","text": "Подготовьте несколько ёлочных игрушек, фигурок или небольших предметов, которые станут героями крошечного мультфильма. Снимайте их по одному кадру, немного перемещая после каждой фотографии, чтобы потом собрать короткую покадровую анимацию. Придумайте историю о том, как обычные вещи оживают в новогоднюю ночь и тайно помогают двум людям найти друг друга.","budget": "free","location": "home","mood": "creative"},{"id": 5157,"title": "Фотоохота за цветами волшебства","text": "Выберите пять цветов, которым присвоите необычные значения: красный — любовь, золотой — удача, синий — мечты, зелёный — надежда, белый — спокойствие. Отправьтесь искать их вокруг себя или на короткой прогулке, фотографируя предметы так, чтобы каждый цвет становился главным героем снимка. Из собранных фотографий создайте маленькую палитру вашей зимы и объясните, почему именно эти находки заслужили место в ней.","budget": "free","location": "outdoor","mood": "creative"},{"id": 5158,"title": "Открытка, которую невозможно нарисовать одному","text": "Возьмите два листа бумаги и договоритесь, что каждый будет создавать только половину одной большой зимней открытки. Не показывайте работы до конца, но заранее придумайте общий символ, который должен находиться на линии соединения двух рисунков. Когда соедините листы, постарайтесь превратить все несовпадения в часть новой сказки, словно ваши разные фантазии неожиданно нашли общий язык.","budget": "free","location": "home","mood": "creative"},{"id": 5159,"title": "Карты зимней судьбы","text": "Создайте собственную колоду романтических карт с необычными названиями: «Хранитель первого снега», «Звезда долгожданной встречи», «Королева нежных слов» и «Мост будущих приключений». Для каждой карты придумайте символический смысл и небольшое действие, которое нужно выполнить после её появления. Разложите карты в случайном порядке и устройте друг другу сказочное гадание, превращая каждое предсказание в возможность создать реальное счастливое событие.","budget": "free","location": "home","mood": "creative"},{"id": 5160,"title": "Атлас вашего сказочного мира","text": "Возьмите большой лист бумаги и вместе нарисуйте карту волшебной страны, существующей только для вашей пары. Добавляйте на неё места с романтическими названиями, реки счастливых случайностей, горы преодолённых трудностей и дворцы будущих мечтаний. После завершения выберите одну неизведанную территорию и договоритесь, какое настоящее приключение позволит вам однажды открыть её на своей карте.","budget": "free","location": "home","mood": "creative"},{"id": 5161,"title": "Радиостанция «Два сердца»","text": "Представьте, что вы ведущие секретной новогодней радиостанции, которая вещает только для двух влюблённых. Запишите небольшой выпуск с романтическими новостями, смешными прогнозами погоды, музыкальными посвящениями и загадочными звонками от вымышленных слушателей. В финале пусть один ведущий неожиданно получит сообщение от тайного поклонника, которым, конечно, окажется его любимый человек.","budget": "free","location": "home","mood": "romantic"},{"id": 5162,"title": "Двенадцать танцев до полуночи","text": "Напишите на двенадцати карточках необычные названия танцев: «Вальс замёрзших звёзд», «Танго снежных духов», «Мелодия первого свидания» и другие. Вытягивайте карточки и придумывайте короткие танцевальные движения, которые соответствуют настроению выпавшей истории. На двенадцатом танце соедините лучшие движения в одну маленькую хореографию, которая станет вашим секретным новогодним танцем.","budget": "free","location": "home","mood": "active"},{"id": 5163,"title": "Оркестр заколдованных вещей","text": "Соберите необычные музыкальные инструменты из безопасных домашних предметов: стаканов, ложек, коробочек с крупой и маленьких колокольчиков. Каждый придумывает короткую мелодию, которая должна символизировать определённое чувство или совместное воспоминание, а второй пытается разгадать его смысл. Когда все мелодии будут сыграны, объедините их в собственную новогоднюю симфонию двух сердец.","budget": "free","location": "home","mood": "romantic"},{"id": 5164,"title": "Аудиоэкскурсия по дому чудес","text": "Превратите собственное жилище в сказочный музей, где каждый обычный предмет обладает таинственной историей. Запишите на телефон короткие экскурсионные рассказы о нескольких вещах, представив, что они являются магическими артефактами, хранящими моменты вашей любви. Обменяйтесь аудиогидами и пройдите маршруты друг друга, открывая знакомый дом с совершенно неожиданной стороны.","budget": "free","location": "home","mood": "cozy"},{"id": 5165,"title": "Создатели звуковой зимы","text": "Представьте, что вы должны озвучить сказочную страну, в которой никогда раньше не существовало зимы. Используйте шуршание бумаги, звон стекла, тихие шаги, дыхание и любые другие безопасные звуки, чтобы придумать звучание снегопада, ледяного дворца и звёздного неба. Запишите получившуюся композицию и вместе придумайте, какая романтическая история могла бы разворачиваться под эту необычную музыку.","budget": "free","location": "home","mood": "creative"},{"id": 5166,"title": "Бал под загадочными масками","text": "Сделайте две бумажные маски, украсив их снежинками, золотыми узорами и маленькими секретными символами. Прежде чем пригласить друг друга на танец, разыграйте встречу таинственных незнакомцев, которым нужно разгадать три загадки, чтобы узнать истинные имена друг друга. Когда последняя тайна откроется, снимите маски и завершите сказочный бал танцем уже без всяких притворств.","budget": "free","location": "home","mood": "creative"},{"id": 5167,"title": "Мелодия, записанная снежинками","text": "Придумайте собственную музыкальную азбуку, в которой изображения снежинок, сердечек, звёзд и ёлочек обозначают определённые звуки или ритмы. Составьте из символов небольшие партитуры и предложите друг другу исполнить их хлопками, колокольчиками или голосом. Соедините две получившиеся мелодии в одну композицию и назовите её в честь вашего самого красивого зимнего воспоминания.","budget": "free","location": "home","mood": "creative"},{"id": 5168,"title": "Саундтрек к тайному воспоминанию","text": "Каждый выбирает одно счастливое событие ваших отношений, но не говорит, какое именно. Подберите несколько музыкальных фрагментов, ритмов или мелодий, которые могли бы стать саундтреком к этому воспоминанию, и включайте их по очереди. Второй должен угадать момент, а затем рассказать, какая музыка звучала бы в его собственной версии этой истории.","budget": "free","location": "home","mood": "romantic"},{"id": 5169,"title": "Музыкальная шкатулка случайностей","text": "Подготовьте небольшой список песен с разным настроением и присвойте каждой номер, спрятав названия от партнёра. Случайно выбирайте номер и вытягивайте дополнительную карточку с действием: придумать танец, описать сказочную сцену или рассказать историю, которую напоминает музыка. Постепенно из этих случайных сочетаний получится целый новогодний спектакль, который невозможно было бы придумать заранее.","budget": "free","location": "home","mood": "creative"},{"id": 5170,"title": "Дирижёр снежной бури","text": "Один из вас становится повелителем воображаемой метели, а второй — снежинкой, которая должна подчиняться взмахам его рук. Придумайте особые жесты для кружения, замирания, медленного падения и внезапного танца, а затем попробуйте провести целую музыкальную сцену. Поменяйтесь ролями и завершите представление моментом, когда две снежинки наконец находят друг друга среди бесконечной зимы.","budget": "free","location": "home","mood": "active"},{"id": 5171,"title": "Радиописьма из разных эпох","text": "Представьте, что вы можете отправлять музыкальные радиопослания друг другу из разных времён. По очереди выбирайте эпоху, придумывайте романтическое обращение и включайте мелодию, которая подходит вашему вымышленному путешествию. Когда дойдёте до далёкого будущего, запишите общее пожелание, будто передаёте его сквозь десятилетия себе настоящим.","budget": "free","location": "home","mood": "romantic"},{"id": 5172,"title": "Тайный ритм наших имён","text": "Придумайте короткие ритмы, которые будут обозначать ваши имена, любимые слова и особенные чувства. Передавайте сообщения друг другу с помощью постукиваний по столу или хлопков, постепенно составляя маленькие музыкальные признания. В конце соедините оба ритма в одну последовательность, которая станет вашим секретным сигналом для самых счастливых моментов.","budget": "free","location": "home","mood": "creative"},{"id": 5173,"title": "Гимн маленького зимнего королевства","text": "Представьте, что вашему личному сказочному королевству необходим собственный новогодний гимн. Вместе сочините несколько оригинальных строк о ваших приключениях, смешных привычках, любимых воспоминаниях и мечтах, подобрав к ним простую мелодию. Устройте торжественную премьеру и запишите исполнение, чтобы однажды снова услышать, какими счастливыми и немного смешными вы были в этот вечер.","budget": "free","location": "home","mood": "creative"},{"id": 5174,"title": "Голос рождественского ангела","text": "Один из вас заранее записывает несколько коротких сообщений от имени доброго праздничного ангела, который наблюдает за вашей историей любви. Включайте записи в случайные моменты вечера, выполняя скрытые внутри задания и получая новые подсказки. Последнее сообщение пусть неожиданно превратится в личное признание, которое будет особенно трогательно услышать в знакомом голосе.","budget": "free","location": "home","mood": "romantic"},{"id": 5175,"title": "Мюзикл одной снежной ночи","text": "Придумайте простую сказочную историю о двух героях, которые отправились спасать пропавшую новогоднюю звезду. Вместо обычных диалогов попробуйте часть реплик напевать, превращая даже самые нелепые разговоры в маленькие музыкальные номера. Разделите спектакль на три действия и придумайте торжественную финальную песню, посвящённую любви, которая помогла героям победить зиму.","budget": "free","location": "home","mood": "creative"},{"id": 5176,"title": "Звуковая карта сокровищ","text": "Подготовьте несколько аудиоподсказок, каждая из которых начинается с характерного звука какого-нибудь предмета в комнате. Второй должен определить источник звука, найти соответствующее место и обнаружить следующую часть музыкальной загадки. Последняя запись приведёт к спрятанному сюрпризу и мелодии, под которую вам предстоит станцевать победный танец.","budget": "free","location": "home","mood": "romantic"},{"id": 5177,"title": "Танец света и музыки","text": "Поставьте несколько безопасных светодиодных огоньков и подготовьте короткие музыкальные фрагменты с разным характером. Для каждой мелодии придумайте свою последовательность движений и включения света, чтобы получился настоящий миниатюрный спектакль. Объедините ваши идеи в одно представление, где свет постепенно собирается вокруг двух влюблённых, словно вся зимняя вселенная решила их обнять.","budget": "free","location": "home","mood": "creative"},{"id": 5178,"title": "Музыкальный компас судьбы","text": "Нарисуйте карту квартиры или небольшого безопасного пространства, обозначив на ней несколько сказочных остановок. На каждой точке спрячьте музыкальную подсказку, которая своим настроением намекает на следующее место или задание. Пройдите весь маршрут, словно путешествуете за потерянной мелодией, и обнаружьте в финале приготовленное друг для друга музыкальное посвящение.","budget": "free","location": "home","mood": "food"},{"id": 5179,"title": "Три минуты, которые умеют слушать","text": "Создайте необычную церемонию из трёх коротких раундов, каждый из которых сопровождается своей тихой мелодией. Во время первого попробуйте выразить благодарность без слов, во время второго передайте друг другу записки с признаниями, а во время третьего просто обнимитесь, слушая музыку вместе. После завершения расскажите, в какой момент вы почувствовали самую сильную близость, и придумайте название вашей маленькой новогодней церемонии.","budget": "free","location": "home","mood": "creative"},{"id": 5180,"title": "Танец по звёздным следам","text": "Вырежьте из бумаги небольшие звёзды и разложите их на полу так, чтобы получилась необычная танцевальная дорожка. На обороте каждой звезды напишите движение или романтическое действие, которое необходимо выполнить, прежде чем перейти к следующей. Пройдите вашу дорожку под музыку, постепенно приближаясь друг к другу, пока последние две звезды не соединятся в одно большое сердце.","budget": "free","location": "home","mood": "creative"},{"id": 5181,"title": "Фестиваль тысячи маленьких чудес","text": "Устройте собственный новогодний фестиваль из пяти миниатюрных волшебных станций, расположенных в разных уголках дома. На одной можно обменивать комплименты на подарки, на другой — проходить сказочные испытания, на третьей — создавать предсказания, а на четвёртой и пятой — открывать новые секретные приключения. Выдайте друг другу фестивальные паспорта и собирайте печати, пока не доберётесь до главного приза вечера.","budget": "free","location": "home","mood": "cozy"},{"id": 5182,"title": "Северное сияние только для нас","text": "Создайте небольшое домашнее северное сияние, направив фонарик через цветную прозрачную плёнку на светлую стену и двигая разноцветные слои. Придумайте легенду о том, что каждый цвет сияния исполняет определённый вид желаний, и по очереди выбирайте оттенки для своих мечтаний. Когда ваша комната наполнится переливами света, обменяйтесь пожеланиями и проведите несколько минут, наблюдая за созданным своими руками небом.","budget": "free","location": "home","mood": "creative"},{"id": 5183,"title": "Бюро предсказаний зимней погоды","text": "Откройте шуточную метеостанцию, которая прогнозирует не температуру и снегопады, а погоду ваших отношений на весь следующий год. Создайте карточки с необычными явлениями: дождём из поцелуев, ураганом приключений, солнечным фронтом нежности и сильным звездопадом желаний. Вытягивайте прогнозы для разных месяцев и придумывайте, какие настоящие события могли бы превратить сказочную погоду в реальность.","budget": "free","location": "home","mood": "romantic"},{"id": 5184,"title": "Космическая новогодняя почта","text": "Представьте, что вы два исследователя космоса, встречающие Новый год на далёкой заснеженной планете. Создайте небольшие космические паспорта, нарисуйте карту звёздной системы и подготовьте друг другу послания, которые якобы путешествовали через тысячи световых лет. Когда письма будут доставлены, придумайте церемонию возвращения на Землю, где самым ценным открытием экспедиции окажется ваша любовь.","budget": "free","location": "home","mood": "creative"},{"id": 5185,"title": "Портал между двумя зимами","text": "Украсьте дверной проём бумажными звёздами и объявите его волшебным порталом, который соединяет два совершенно разных мира. Каждый создаёт по одну сторону двери своё королевство со специальными законами, тайными заданиями и маленькими сюрпризами для путешественника. Обменяйтесь приглашениями и исследуйте миры друг друга, пока не найдёте способ объединить их в одну прекрасную вселенную.","budget": "free","location": "home","mood": "active"},{"id": 5186,"title": "Музей бесценных подарков","text": "Договоритесь создать друг для друга подарки, на которые нельзя потратить ни одной монетки. Это могут быть нарисованные карты воспоминаний, записанные истории, сертификаты на необычные приключения или собственноручно созданные талисманы. Устройте выставку получившихся сокровищ и проведите экскурсию, объясняя, почему каждый из этих подарков невозможно оценить деньгами.","budget": "free","location": "home","mood": "romantic"},{"id": 5187,"title": "Морозные узоры, хранящие секреты","text": "Используйте смываемые маркеры для стекла, подходящие для вашей поверхности, и нарисуйте на окне небольшие морозные узоры. Внутри каждого узора спрячьте загадочные символы и слова, которые второй должен обнаружить, внимательно рассматривая рисунок. Когда все секреты будут найдены, соедините их в одну романтическую историю и оставьте самый красивый узор до следующего маленького зимнего чуда.","budget": "free","location": "home","mood": "creative"},{"id": 5188,"title": "Снеговик, который умеет исполнять мечты","text": "Создайте необычного снеговика из белых подушек, ткани или бумаги, даже если за окном совсем нет снега. Каждый элемент его внешности должен быть заслужен выполнением маленького задания, а за глаза, шарф и пуговицы снеговик будет выдавать новые предсказания. Когда ваш волшебный гость наконец оживёт, вложите в его карман два желания и придумайте сказку о том, как он поможет им исполниться.","budget": "free","location": "home","mood": "creative"},{"id": 5189,"title": "Сто шагов до новогоднего чуда","text": "Заранее придумайте короткий безопасный маршрут, разделённый на десять этапов примерно по десять шагов каждый. На каждой остановке открывайте карточку с загадкой, комплиментом или мини-испытанием, которые будут постепенно раскрывать историю о потерянном новогоднем сокровище. Сотый шаг должен привести вас к красивому месту или приготовленному сюрпризу, где вы узнаете, что настоящим сокровищем всё время было ваше путешествие вместе.","budget": "free","location": "home","mood": "food"},{"id": 5190,"title": "Письмо на снежной канатной дороге","text": "Протяните между двумя устойчивыми точками в комнате верёвочку и сделайте маленькую бумажную кабинку, которая сможет скользить по ней. Превратите её в волшебную почтовую дорогу между двумя далёкими зимними королевствами и передавайте друг другу крошечные письма, загадки и сувениры. Постепенно сокращайте расстояние между королевствами, пока последняя записка не окажется личным приглашением встретиться посередине.","budget": "free","location": "home","mood": "romantic"},{"id": 5191,"title": "Встреча на новогоднем балу сто лет назад","text": "Представьте, что вы перенеслись в прошлое на целое столетие и встретились на роскошном зимнем балу, где никто не знает ваших настоящих имён. Подготовьте бумажные приглашения, придумайте старинные манеры и сыграйте незнакомцев, которые должны узнать друг друга по трём загадочным признакам. Когда тайна раскроется, напишите совместное письмо в будущее, словно оставляете потомкам свидетельство необыкновенной любви.","budget": "free","location": "home","mood": "creative"},{"id": 5192,"title": "Лабиринт замёрзших желаний","text": "Создайте на полу лабиринт из бумажных дорожек, лент или листов с нарисованными снежинками. В нескольких тупиках спрячьте забавные испытания, а в центре разместите шкатулку с заданием, которое невозможно выполнить в одиночку. Найдите путь вместе, помогая друг другу проходить препятствия, и откройте шкатулку, когда ваши маршруты наконец соединятся.","budget": "free","location": "home","mood": "romantic"},{"id": 5193,"title": "Совет волшебных зимних зверей","text": "Соберите несколько игрушечных зверей или сделайте их бумажные фигурки, назначив каждому особую роль в сказочном зимнем лесу. Мудрая сова будет задавать загадки, лиса — придумывать хитрые испытания, заяц — просить о добрых поступках, а медведь — охранять секретное сокровище. Проходите задания зверей по очереди, чтобы получить разрешение войти в самую таинственную часть леса, где хранится подарок для двух влюблённых.","budget": "free","location": "home","mood": "active"},{"id": 5194,"title": "Экспресс до станции «Счастье»","text": "Превратите несколько уголков дома в вагоны волшебного новогоднего поезда, который отправляется в путешествие по невероятным мирам. Изготовьте билеты и устройте пересадки на станциях «Заснеженный Париж», «Королевство звёзд», «Лес забытых сказок» и «Планета любви», выполняя в каждом вагоне тематические задания. Последней остановкой станет уютное место, где вас будет ждать праздничный сюрприз и записка с обещанием нового путешествия.","budget": "free","location": "home","mood": "cozy"},{"id": 5195,"title": "Отдел исполнения забытых просьб","text": "Представьте, что вы случайно нашли секретное бюро Деда Мороза, куда попадают желания, которые люди когда-то загадали, но потом забыли. Подготовьте друг для друга карточки с небольшими старыми мечтами, забавными просьбами и желаниями, которые ещё можно исполнить. Станьте новогодними волшебниками и попробуйте воплотить хотя бы три из них прямо сейчас, доказывая, что для маленького чуда иногда достаточно двух любящих людей.","budget": "free","location": "home","mood": "romantic"},{"id": 5196,"title": "Три невозможных новогодних задания","text": "Напишите друг другу по три на первый взгляд невыполнимых задания: поймать звезду, подарить кусочек луны, остановить снегопад или построить дворец за десять минут. Вместо буквального исполнения используйте фантазию и обычные предметы, например сделайте звезду из бумаги, луну из светящегося круга или дворец из одеял. Наградите друг друга за самые красивые решения и сохраните получившиеся чудеса как доказательство того, что волшебство часто начинается с воображения.","budget": "free","location": "home","mood": "creative"},{"id": 5197,"title": "Дерево, на котором растут мечты","text": "Возьмите красивую опавшую веточку, поставьте её в вазу и превратите в необычное дерево зимних желаний. Каждый изготовит несколько маленьких бумажных плодов, внутри которых спрячутся мечты, предложения для свиданий и добрые обещания. По очереди срывайте плоды с дерева, читая послания, а затем повесьте новые украшения за каждое желание, которое решите исполнить вместе.","budget": "free","location": "home","mood": "romantic"},{"id": 5198,"title": "Четыре свидания за один волшебный вечер","text": "Создайте четыре маленьких мира, каждый из которых подарит вам отдельное пятнадцатиминутное свидание. В первом вы станете путешественниками ледяного королевства и разгадаете карту, во втором — гостями таинственного бала, в третьем — исследователями звёзд, а в четвёртом — двумя незнакомцами, чьи судьбы соединила новогодняя магия. Подготовьте для каждого мира отдельный конверт с заданием и перемещайтесь между ними, словно проживаете четыре разные сказки за одну ночь.","budget": "free","location": "home","mood": "creative"},{"id": 5199,"title": "Школа волшебства для двух сердец","text": "Каждый заранее придумывает по три маленьких волшебных урока, которым сможет научить любимого человека. Это могут быть фокусы с бумажными фигурками, искусство создавать тайные шифры, необычная техника рисования или секретный танец, который знаете только вы. В конце обменяйтесь дипломами сказочных магов и устройте выпускной экзамен, на котором нужно объединить новые умения, чтобы создать одно общее романтическое чудо.","budget": "free","location": "home","mood": "romantic"},{"id": 5200,"title": "Полночь, которая принадлежит только вам","text": "Выберите любое время вечера и объявите, что именно тогда наступит ваш собственный маленький Новый год, независимо от даты в календаре. Подготовьте двенадцать символических ударов часов, за каждым из которых будет скрываться отдельное воспоминание, благодарность, признание или желание, и открывайте их по очереди при свете гирлянд. Когда прозвучит воображаемый последний удар, обменяйтесь тайными обещаниями и поцелуем, начиная новую главу вашей сказки в тот самый момент, который вы выбрали сами.","budget": "free","location": "home","mood": "romantic"}];
